class FirSessionConfigurator(private val session: FirSession) {
    private val registeredExtensions: MutableList<BunchOfRegisteredExtensions> = mutableListOf(BunchOfRegisteredExtensions.empty())
    private var filterPlatformSpecificCheckers: Boolean = false

    fun registerExtensions(extensions: BunchOfRegisteredExtensions) {
        registeredExtensions += extensions
    }

    /**
     * Must only be used in CLI compiler mode.
     */
    @OptIn(SessionConfiguration::class)
    fun useCheckers(checkers: ExpressionCheckers) {
        val checkers = if (filterPlatformSpecificCheckers) {
            FilteredExpressionCheckers(checkers) { it.platformSpecificCheckerEnabledInMetadataCompilation }
        } else {
            checkers
        }
        session.checkersComponent.register(checkers)
    }

    /**
     * Must only be used in CLI compiler mode.
     */
    @OptIn(SessionConfiguration::class)
    fun useCheckers(checkers: DeclarationCheckers) {
        val checkers = if (filterPlatformSpecificCheckers) {
            FilteredDeclarationCheckers(checkers) { it.platformSpecificCheckerEnabledInMetadataCompilation }
        } else {
            checkers
        }
        session.checkersComponent.register(checkers)
    }

object FirUnusedExpressionChecker : FirUnusedCheckerBase() {
    context(context: CheckerContext)
    override fun isEnabled(): Boolean = true // Controlled by FIR_EXTRA_CHECKERS

    context(context: CheckerContext, reporter: DiagnosticReporter)
    override fun createVisitor(): UsageVisitorBase = UsageVisitor(context, reporter)

    context(context: CheckerContext, reporter: DiagnosticReporter)
    private fun reportUnused(
        expression: FirExpression,
        source: KtSourceElement?,
    ) {
        val isLambda = expression is FirAnonymousFunctionExpression && expression.anonymousFunction.isLambda
        val factory = when {
            isLambda
                -> FirErrors.UNUSED_LAMBDA_EXPRESSION
            else -> FirErrors.UNUSED_EXPRESSION
        }
        reporter.reportOn(source, factory)
    }

    private class UsageVisitor(context: CheckerContext, reporter: DiagnosticReporter) : UsageVisitorBase(context, reporter) {
        override fun checkExpression(
            expression: FirExpression,
            data: UsageState,
        ) {
            if (!data.isUnused()) return
            if (expression.hasSideEffect()) return
            context(context, reporter) {
                reportUnused(expression, expression.source)
            }
        }

abstract class FirUnusedCheckerBase : FirBasicDeclarationChecker(MppCheckerKind.Common) {
    context(context: CheckerContext)
    abstract fun isEnabled(): Boolean

    context(context: CheckerContext, reporter: DiagnosticReporter)
    protected abstract fun createVisitor(): UsageVisitorBase

    context(context: CheckerContext, reporter: DiagnosticReporter)
    override fun check(declaration: FirDeclaration) {
        if (!isEnabled()) return
        if (context.isContractBody) return
        val visitor = createVisitor()
        when (declaration) {
            // A "used" FirBlock is one that uses the last statement as an implicit return.
            // If the containing element of the block is an FirFunction or FirAnonymousInitializer, the block is unused.
            // All other FirBlocks are considered used.
            is FirCodeFragment -> declaration.block.acceptChildren(visitor, UsageState.Used)
            is FirAnonymousInitializer -> declaration.body?.acceptChildren(visitor, UsageState.Unused)
            is FirAnonymousFunction -> { /* Visitor checks anonymous functions in-place */ }
            is FirFunction -> {
                declaration.body?.accept(visitor, UsageState.Unused)
            }

            // Variables are special as they have an FirExpression as the entry point, which is always used.
            is FirVariable -> {
                declaration.initializer?.accept(visitor, UsageState.Used)
                declaration.delegate?.accept(visitor, UsageState.Used)
            }

            else -> {} // Other declarations are not checked.
        }
    }

override fun visitBlock(block: FirBlock, data: UsageState) {
    if (block is FirContractCallBlock) return
    // Increment and decrement operators are always considered used (because they have a side effect).
    if (block.source?.kind is KtFakeSourceElementKind.DesugaredIncrementOrDecrement) return

    val statements = block.statements
    val lastIndex = statements.lastIndex
    for (i in statements.indices) {
        val statement = statements[i]
        val isUsed = when {
            block.isUnitCoerced -> UsageState.UnusedFromCoercion
            i == lastIndex -> data // is implicit return
            else -> UsageState.Unused
        }
        statement.accept(this, isUsed)
    }
}

override fun visitLoop(loop: FirLoop, data: UsageState) {
    loop.condition.accept(this, UsageState.Used)
    loop.block.accept(this, UsageState.Unused)
}

internal fun FirExpression.hasSideEffect(): Boolean {
    return when (this) {
        // Literals and references that are known to be side-effect-free.
        is FirLiteralExpression,
        is FirClassReferenceExpression,
        is FirResolvedQualifier,
        is FirThisReceiverExpression,
            -> false

        // The definition of an anonymous function is side-effect-free.
        // Invoking an anonymous function has side effects, but this is performed by another FIR element.
        is FirAnonymousFunctionExpression,
            -> false

        // A smart cast has a side effect iff its original expression has a side effect.
        is FirSmartCastExpression -> {
            originalExpression.hasSideEffect()
        }

        // A callable reference is side-effect-free only if all of its receivers are side-effect-free.
        is FirCallableReferenceAccess -> {
            dispatchReceiver?.hasSideEffect() == true ||
                    extensionReceiver?.hasSideEffect() == true ||
                    explicitReceiver?.hasSideEffect() == true
        }

        // String concatenation and class access are side-effect-free if all arguments are side-effect-free.
        is FirStringConcatenationCall,
        is FirGetClassCall,
            -> {
            arguments.any { it.hasSideEffect() }
        }

        // Property access is side-effect-free if the referenced property does not have a custom getter.
        // However, this check is limited to just considering value parameters, receiver parameters, and
        // local properties without delegates as side-effect-free, to be conservative and match K1 behavior.
        is FirPropertyAccessExpression -> {
            if (source?.kind == KtFakeSourceElementKind.ReferenceInAtomicQualifiedAccess) true
            else when (val propertySymbol = calleeReference.symbol) {
                is FirValueParameterSymbol, is FirReceiverParameterSymbol -> false
                is FirLocalPropertySymbol -> propertySymbol.hasDelegate
                else -> true
            }
        }

        else -> true
    }

override fun checkExpression(expression: FirExpression, data: UsageState) {
    when (data) {
        is UsageState.Used -> return
        is UsageState.UsedInReturn -> if (data.returnExpression !in returnsToCheck) return
        else -> if (!expression.hasSideEffect()) return // Do not report anything FirUnusedExpressionChecker already reported
    }

    context(context, reporter) {
        checkIfExpressionUnused(expression, data)
    }

object ArrayEqualityCanBeReplacedWithContentEquals : FirBasicExpressionChecker(MppCheckerKind.Common) {
    private val ARRAY_CLASS_IDS = buildList {
        add(StandardClassIds.Array)
        addAll(StandardClassIds.primitiveArrayTypeByElementType.values)
        addAll(StandardClassIds.unsignedArrayTypeByElementType.values)
    }

    context(context: CheckerContext, reporter: DiagnosticReporter)
    override fun check(expression: FirStatement) {
        if (expression !is FirEqualityOperatorCall) return
        if (expression.operation.let { it != FirOperation.EQ && it != FirOperation.NOT_EQ }) return
        val arguments = expression.arguments
        val left = arguments.getOrNull(0) ?: return
        val right = arguments.getOrNull(1) ?: return

        val leftClassId = left.resolvedType.arrayClassId().takeIf { it != -1 }
        val rightClassId = right.resolvedType.arrayClassId()

        if (leftClassId == rightClassId) {
            reporter.reportOn(
                expression.source, ARRAY_EQUALITY_OPERATOR_CAN_BE_REPLACED_WITH_CONTENT_EQUALS,
                expression.operation.operator,
                if (expression.operation == FirOperation.NOT_EQ) "!" else "",
            )
        }
    }

    context(context: CheckerContext)
    private fun ConeKotlinType.arrayClassId(): Int {
        var result = -1

        forEachClassId {
            val index = ARRAY_CLASS_IDS.indexOf(it)
            if (index != -1) result = index
        }

        return result
    }

object RedundantCallOfConversionMethodChecker : FirFunctionCallChecker(MppCheckerKind.Common) {
    private val unsafeNumberClassId = ClassId.fromString("kotlinx.cinterop/UnsafeNumber")

    context(context: CheckerContext, reporter: DiagnosticReporter)
    override fun check(expression: FirFunctionCall) {
        if (expression.extensionReceiver != null) return
        val functionName = expression.calleeReference.name
        val qualifiedTypeId = targetClassMap[functionName] ?: return

        if (expression.dispatchReceiver?.isRedundant(qualifiedTypeId, context.session) == true) {
            reporter.reportOn(expression.source, FirErrors.REDUNDANT_CALL_OF_CONVERSION_METHOD)
        }
    }

    context(context: CheckerContext)
    private fun FirExpression.isRedundant(qualifiedClassId: ClassId, session: FirSession): Boolean {
        if (hasIntegerLiteralTypeAmbiguity()) return false

        val thisTypeId = if (this is FirLiteralExpression) {
            resolvedType.classId
        } else {
            when {
                resolvedType is ConeFlexibleType -> null
                resolvedType.isMarkedNullable -> null
                resolvedType.abbreviatedTypeOrSelf.toClassLikeSymbol()?.hasAnnotation(unsafeNumberClassId, session) == true -> null
                else -> resolvedType.fullyExpandedClassId(session)
            }
        }
        return thisTypeId == qualifiedClassId
    }

    private val targetClassMap: HashMap<Name, ClassId> = hashMapOf(
        OperatorNameConventions.TO_STRING to StandardClassIds.String,
        OperatorNameConventions.TO_DOUBLE to StandardClassIds.Double,
        OperatorNameConventions.TO_FLOAT to StandardClassIds.Float,
        OperatorNameConventions.TO_LONG to StandardClassIds.Long,
        OperatorNameConventions.TO_INT to StandardClassIds.Int,
        OperatorNameConventions.TO_CHAR to StandardClassIds.Char,
        OperatorNameConventions.TO_SHORT to StandardClassIds.Short,
        OperatorNameConventions.TO_BYTE to StandardClassIds.Byte,
        OperatorNameConventions.TO_ULONG to StandardClassIds.ULong,
        OperatorNameConventions.TO_UINT to StandardClassIds.UInt,
        OperatorNameConventions.TO_USHORT to StandardClassIds.UShort,
        OperatorNameConventions.TO_UBYTE to StandardClassIds.UByte
    )

    // TODO, KT-59831: report case like "a += 1" where `a` `doesn't writes` different way (special for Idea)
    reporter.reportOn(statement.lValue.source, FirErrors.ASSIGNED_VALUE_IS_NEVER_READ)
}

